using System.Collections.Concurrent;using System.Net;using System.Net.Http;using System.Reflection;using System.Text;using TownOfHost;
partial class Program {
static byte[] EofBatch(string next,params byte[][] messages)=>Proto(string.IsNullOrEmpty(next)?Array.Empty<byte>():Str(100602,next),Proto(messages.Select(x=>Bin(1007,x)).ToArray()));
static string FutureMessageTime()=>DateTimeOffset.UtcNow.AddMinutes(1).ToString("O");
static StreamerInfo OwnerFor(IYouTubeChatSource source){YouTubeOfficialRuntime.Factory=()=>source;int epoch=(int)typeof(StreamerInfo).GetField("epoch",flags).GetValue(null);var info=(StreamerInfo)Activator.CreateInstance(typeof(StreamerInfo),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{Video,epoch},null);typeof(StreamerInfo).GetField("current",flags).SetValue(null,info);return info;}
static int NormalWait(bool progress,bool resume,ref int idle){var m=typeof(StreamerInfo).GetMethod("NormalWaitSeconds",BindingFlags.Static|BindingFlags.NonPublic);Check(m!=null,"normal wait policy missing");object[] args={progress,resume,idle};int delay=(int)m.Invoke(null,args);idle=(int)args[2];return delay;}
static void RunNormalEof(){
Test("normal grpc zero EOF returns successfully rather than network failure",()=>{var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-next",Message()))));using(s)SourceRun(s).GetAwaiter().GetResult();Check(d.Last().Code==YouTubeChatCode.EndOfStream&&d.Last().GrpcStatus==0&&d.Last().ExceptionKind==YouTubeChatExceptionKind.None&&d.Last().Failure==null);SafeChat(d);});
Test("normal EOF resume token is included on the next request",()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-page-a",Message(id:"a")))),JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-page-b",Message(id:"b")))));using(s){SourceRun(s).GetAwaiter().GetResult();SourceRun(s).GetAwaiter().GetResult();}Check(h.Requests.Count==4&&Encoding.UTF8.GetString(h.Requests[3].Body).Contains("eof-page-a")&&!Encoding.UTF8.GetString(h.Requests[1].Body).Contains("eof-page-a"));});
Test("five consecutive grpc zero responses never throw a retry-exhausted failure",()=>{var responses=new List<HttpResponseMessage>();for(int n=0;n<5;n++){responses.Add(JsonReply(LiveJson()));responses.Add(GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("page-"+n,Message(id:"m"+n)))));}var(s,h)=Api(false,responses.ToArray());using(s)for(int n=0;n<5;n++)SourceRun(s).GetAwaiter().GetResult();Check(h.Requests.Count==10);});
foreach(bool frame in new[]{false,true})Test("empty successful response without continuation is safe "+frame,()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(frame?YouTubeGrpcProtocol.Frame(EofBatch("")):Array.Empty<byte>()),JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>()));using(s){SourceRun(s).GetAwaiter().GetResult();SourceRun(s).GetAwaiter().GetResult();}var expected=YouTubeGrpcProtocol.Frame(Proto(Str(1,"chat-id"),Str(2,"ja"),Str(100,"id"),Str(100,"snippet"),Str(100,"authorDetails")));Check(h.Requests[3].Body.SequenceEqual(expected));});
Test("empty response retains last known continuation instead of losing it",()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-retained",Message()))),JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>()),JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>()));using(s)for(int n=0;n<3;n++)SourceRun(s).GetAwaiter().GetResult();Check(Encoding.UTF8.GetString(h.Requests[3].Body).Contains("eof-retained")&&Encoding.UTF8.GetString(h.Requests[5].Body).Contains("eof-retained"));});
Test("trailers-only grpc zero is a normal successful completion",()=>{var response=GrpcReply(Array.Empty<byte>(),null);response.Headers.Add("grpc-status","0");var(s,h)=Api(false,JsonReply(LiveJson()),response);using(s)SourceRun(s).GetAwaiter().GetResult();Check(h.Requests.Count==2);});
foreach(var kind in new[]{(false,false),(false,true),(true,false)})Test("no-progress or missing-token completion backs off "+kind,()=>{int idle=0;var values=Enumerable.Range(0,8).Select(_=>NormalWait(kind.Item1,kind.Item2,ref idle)).ToArray();Check(values.SequenceEqual(new[]{5,10,20,40,60,60,60,60}));});
Test("continuation progress resets idle delay without touching network policy",()=>{int idle=5;Check(NormalWait(true,true,ref idle)==5&&idle==0);Check(NormalWait(false,true,ref idle)==5&&idle==1);});
foreach(int initial in new[]{-1,int.MaxValue})Test("idle wait counter is bounded "+initial,()=>{int idle=initial;int delay=NormalWait(false,false,ref idle);Check(delay>=5&&delay<=60&&idle>=1&&idle<=5);});
Test("real gRPC unavailable still throws the original retryable error",()=>{var(s,h,d)=DiagnosticApi(JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>(),"14"));using(s)Deny(YouTubeFailure.NetworkInterrupted,()=>SourceRun(s).GetAwaiter().GetResult());Check(d.Last().Code==YouTubeChatCode.GrpcRejected&&d.Last().GrpcStatus==14);});
Test("missing gRPC status is not accepted as normal completion",()=>{var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(Array.Empty<byte>(),null));using(s)Deny(YouTubeFailure.InvalidResponse,()=>SourceRun(s).GetAwaiter().GetResult());});
Test("ended broadcast never starts another gRPC request",()=>{var(s,h)=Api(false,JsonReply(LiveJson("\"actualEndTime\":\"2026-11-13T00:00:00Z\"")));using(s)Deny(YouTubeFailure.LiveEnded,()=>SourceRun(s).GetAwaiter().GetResult());Check(h.Requests.Count==1);});
Test("Japanese and English queue dedup survive normal reconnect",()=>{ResetStream();YouTubeOfficialRuntime.ParticipationPolicyReviewed=false;var time=FutureMessageTime();var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-q-a",Message(id:"history",text:"日本語の履歴"),Message(id:"live",text:"English live",time:time)))),JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-q-b",Message(id:"history",text:"日本語の履歴"),Message(id:"live",text:"English live",time:time),Message(id:"live2",text:"日本語ライブ",time:time)))));var i=OwnerFor(s);try{i.FetchAsync().GetAwaiter().GetResult();Drain();i.FetchAsync().GetAwaiter().GetResult();Drain();Check(StreamerInfo.RecentComments.Select(x=>x.Text).SequenceEqual(new[]{"日本語の履歴","English live","日本語ライブ"})&&StreamerInfo.Interests.Count==0&&h.Requests.Count==4);}finally{StreamerInfo.StopNetwork();WaitFetch();}});
Test("initial history is not replayed after its IDs leave the bounded dedup window",()=>{ResetStream();YouTubeOfficialRuntime.ParticipationPolicyReviewed=false;var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-history-a",Message(id:"old",text:"initial-only")))),JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-history-b",Message(id:"old",text:"initial-only"),Message(id:"new",text:"new-live",time:FutureMessageTime())))));var i=OwnerFor(s);try{i.FetchAsync().GetAwaiter().GetResult();Drain();for(int n=0;n<600;n++){Queue(i,"evict-"+n,"channel","filler",true);if(n%100==99)Drain();}Check(!StreamerInfo.RecentComments.Any(x=>x.Text=="initial-only"));i.FetchAsync().GetAwaiter().GetResult();Drain();Check(!StreamerInfo.RecentComments.Any(x=>x.Text=="initial-only")&&StreamerInfo.RecentComments.Any(x=>x.Text=="new-live"));}finally{StreamerInfo.StopNetwork();WaitFetch();}});
Test("history remains available if first request fails before receiving anything",()=>{ResetStream();var(s,h)=Api(false,JsonReply("{}",HttpStatusCode.ServiceUnavailable),JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-first-ok",Message(text:"first-history")))));var i=OwnerFor(s);try{Deny(YouTubeFailure.NetworkInterrupted,()=>i.FetchAsync().GetAwaiter().GetResult());i.FetchAsync().GetAwaiter().GetResult();Drain();Check(StreamerInfo.RecentComments.Single().Text=="first-history");}finally{StreamerInfo.StopNetwork();WaitFetch();}});
Test("partial history is not replayed after a real stream error",()=>{ResetStream();var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-partial",Message(id:"h1",text:"first-history"))),"14"),JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("eof-partial2",Message(id:"h1",text:"first-history"),Message(id:"h2",text:"older-history"),Message(id:"new",text:"new-live",time:FutureMessageTime())))));var i=OwnerFor(s);try{Deny(YouTubeFailure.NetworkInterrupted,()=>i.FetchAsync().GetAwaiter().GetResult());Drain();i.FetchAsync().GetAwaiter().GetResult();Drain();Check(StreamerInfo.RecentComments.Select(x=>x.Text).SequenceEqual(new[]{"first-history","new-live"}));}finally{StreamerInfo.StopNetwork();WaitFetch();}});
Test("normal owner reconnect continues beyond four successes without network errors",()=>{ResetStream();YouTubeOfficialRuntime.ParticipationPolicyReviewed=false;var old=YouTubeOfficialRuntime.Diagnostics;var logs=new ConcurrentQueue<YouTubeChatDiagnostic>();YouTubeOfficialRuntime.Diagnostics=logs.Enqueue;var h=new ApiHandler();for(int n=0;n<4;n++){h.Responses.Enqueue(JsonReply(LiveJson()));h.Responses.Enqueue(GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("owner-page-"+n,Message(id:"owner-"+n,text:n%2==0?"日本語":"English",time:FutureMessageTime())))));}h.Responses.Enqueue(JsonReply(LiveJson()));var quiet=GrpcReply(Array.Empty<byte>());quiet.Content=new StreamContent(new NeverReadStream());quiet.Content.Headers.ContentType=new("application/grpc");h.Responses.Enqueue(quiet);var s=new OfficialYouTubeChatSource(new MemoryYouTubeCredentials(Credential()),new HttpClient(h));OwnerFor(s);TownOfHost.Main.ShowStreamComments.Value=true;try{StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>h.Requests.Count==10,35000),"normal reconnect stopped before fifth call");Drain();Check(StreamerInfo.RecentComments.Count==4&&TownOfHost.Logger.Warnings.Count==0&&!logs.Any(x=>x.Code==YouTubeChatCode.RetryExhausted||x.Code==YouTubeChatCode.RetryScheduled)&&logs.Count(x=>x.Stage==YouTubeChatStage.Retry&&x.Code==YouTubeChatCode.Renewal)==4);SafeChat(logs);}finally{StreamerInfo.StopNetwork();WaitFetch();YouTubeOfficialRuntime.Diagnostics=old;}});
foreach(bool turnOff in new[]{false,true})Test("manual stop or OFF cancels normal reconnect wait "+turnOff,()=>{ResetStream();var old=YouTubeOfficialRuntime.Diagnostics;var logs=new ConcurrentQueue<YouTubeChatDiagnostic>();YouTubeOfficialRuntime.Diagnostics=logs.Enqueue;var h=new ApiHandler();h.Responses.Enqueue(JsonReply(LiveJson()));h.Responses.Enqueue(GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("owner-stop",Message(time:FutureMessageTime())))));OwnerFor(new OfficialYouTubeChatSource(new MemoryYouTubeCredentials(Credential()),new HttpClient(h)));TownOfHost.Main.ShowStreamComments.Value=true;try{StreamerInfo.CommentFrameTick(.02f);Check(SpinWait.SpinUntil(()=>logs.Any(x=>x.Stage==YouTubeChatStage.Retry&&x.Code==YouTubeChatCode.Renewal),3000));if(turnOff){TownOfHost.Main.ShowStreamComments.Value=false;StreamerInfo.CommentFrameTick(.02f);}else StreamerInfo.StopNetwork();WaitFetch();Check(h.Requests.Count==2&&StreamerInfo.Status==StreamerInfo.ConnectionStatus.Paused&&TownOfHost.Logger.Warnings.Count==0);}finally{StreamerInfo.StopNetwork();WaitFetch();YouTubeOfficialRuntime.Diagnostics=old;}});
Test("owner live-ended event stops without reconnect",()=>{ResetStream();var(s,h)=Api(false,JsonReply(LiveJson()),GrpcReply(YouTubeGrpcProtocol.Frame(EofBatch("",Message(type:4)))));OwnerFor(s);TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);WaitFetch();Check(h.Requests.Count==2&&StreamerInfo.Status==StreamerInfo.ConnectionStatus.LiveEnded);StreamerInfo.StopNetwork();WaitFetch();});
Test("OFF before starting normal source causes zero requests",()=>{ResetStream();var(s,h)=Api();OwnerFor(s);StreamerInfo.CommentFrameTick(.02f);Check(h.Requests.Count==0&&StreamerInfo.Status==StreamerInfo.ConnectionStatus.Paused);});
}
